export function mountTooltips(){const tip=document.createElement('div');tip.className='muse-tooltip';tip.id='muse-tooltip';tip.setAttribute('role','tooltip');document.body.appendChild(tip);let timer=null,current=null,previousTitle='';const descriptions={'So sánh':'Đối chiếu ảnh gốc và thành phẩm','Ảnh gốc':'Xem ảnh đầu vào','Thành phẩm':'Xem ảnh đã tạo','Tối ưu prompt':'Làm rõ yêu cầu, giữ ý tưởng','Vẽ vùng sửa':'Khoanh phần cần thay đổi','Dùng thành phẩm làm ảnh đầu vào':'Tiếp tục sáng tạo từ ảnh này','Tải kết quả':'Lưu tệp về máy','Toàn màn hình':'Mở rộng vùng xem','Đặt lại góc nhìn':'Đưa ảnh về kích thước ban đầu','Zoom song song hai ảnh':'Phóng hai ảnh cùng lúc','Zoom riêng từng ảnh':'Phóng từng ảnh độc lập','Ẩn lịch sử':'Thu gọn danh sách ảnh','Hiện lịch sử':'Mở danh sách ảnh đã tạo'};function hide(){clearTimeout(timer);tip.classList.remove('is-visible');if(current){if(previousTitle)current.setAttribute('title',previousTitle);current.removeAttribute('aria-describedby')}current=null}function show(el){if(el===current)return;hide();const label=el.getAttribute('aria-label')||el.getAttribute('title')||el.textContent.trim();if(!label)return;current=el;previousTitle=el.getAttribute('title')||'';el.removeAttribute('title');timer=setTimeout(()=>{if(!el.isConnected)return;tip.replaceChildren();const strong=document.createElement('strong');strong.textContent=window.museTranslateLabel?.(label)||label;tip.appendChild(strong);const description=descriptions[label]||Object.entries(descriptions).find(([vi])=>(window.museTranslateLabel?.(vi)||vi)===label)?.[1];if(description){const span=document.createElement('span');span.textContent=window.museTranslateLabel?.(description)||description;tip.appendChild(span)}tip.classList.add('is-visible');el.setAttribute('aria-describedby',tip.id);const r=el.getBoundingClientRect(),t=tip.getBoundingClientRect();tip.style.left=Math.max(8,Math.min(innerWidth-t.width-8,r.left+r.width/2-t.width/2))+'px';tip.style.top=(r.bottom+t.height+12<innerHeight?r.bottom+8:Math.max(8,r.top-t.height-8))+'px'},320)}function over(e){const el=e.target.closest?.('button,a,[role=tab]');if(el&&(el.querySelector('svg')||el.hasAttribute('title')))show(el)}function out(e){if(current&&!current.contains(e.relatedTarget))hide()}document.addEventListener('pointerover',over);document.addEventListener('pointerout',out);document.addEventListener('focusin',over);document.addEventListener('focusout',hide);document.addEventListener('pointerdown',hide);window.addEventListener('scroll',hide,true);return()=>{hide();tip.remove();document.removeEventListener('pointerover',over);document.removeEventListener('pointerout',out);document.removeEventListener('focusin',over);document.removeEventListener('focusout',hide);document.removeEventListener('pointerdown',hide);window.removeEventListener('scroll',hide,true)}}
